messages.content:
Tool response:
Tool: create_contact_note
Description: Create Contact Note
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_mrn": {
          "type": "string",
          "description": "Medical Record Number of the patient",
          "title": "Patient Mrn"
        },
        "author_user_id": {
          "type": "integer",
          "description": "ID of the user creating the note",
          "title": "Author User Id"
        },
        "contact_datetime": {
          "type": "string",
          "description": "Date and time of the contact in ISO format",
          "title": "Contact Datetime"
        },
        "duration_minutes": {
          "type": "integer",
          "description": "Duration of the contact in minutes",
          "title": "Duration Minutes"
        },
        "contact_method": {
          "type": "string",
          "description": "Method of contact (phone, in-person, video, email, portal, other)",
          "title": "Contact Method"
        },
        "transcription_enabled": {
          "type": "boolean",
          "description": "Whether voice-to-text transcription was enabled",
          "title": "Transcription Enabled"
        },
        "note_text": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Text content of the note",
          "title": "Note Text"
        },
        "care_plan_identifier": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Identifier of the care plan to link",
          "title": "Care Plan Identifier"
        },
        "care_plan_version": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Version of the care plan to link",
          "title": "Care Plan Version"
        },
        "task_identifier": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Identifier of the task to link",
          "title": "Task Identifier"
        },
        "tag_names": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "description": "Names of tags to associate with the note",
          "title": "Tag Names"
        }
      },
      "required": [
        "patient_mrn",
        "author_user_id",
        "contact_datetime",
        "duration_minutes",
        "contact_method",
        "transcription_enabled"
      ]
    }
